package com.nvv.mediadata.data.model.tmdbimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializable@Serializabledata class AuthorDetails(	@SerialName("name") val name: String,	@SerialName("username") val username: String,	@SerialName("avatar_path") val avatarPath: String?,	@SerialName("rating") val rating: Double)fun AuthorDetails.getAvatar() : String {	return BaseURLTheMovieDatabaseImage + LogoTheMovieDatabase + (this.avatarPath ?: "")}@Serializabledata class Review(	@SerialName("author") val author: String = "",	@SerialName("author_details") val authorDetails: AuthorDetails,	@SerialName("content") val content: String = "",	@SerialName("created_at") val createdAt: String = "",	@SerialName("id") val id: String = "",	@SerialName("updated_at") val updatedAt: String = "",	@SerialName("url") val url: String = "")